C++Lua <pre><code>void Fishing::onLoad(const ScriptContext&amp;) override {
    // (no-op; declareBreakAware must come from a callback)
}

void Fishing::onTick(const ScriptContext&amp; ctx) override {
    using namespace srs::api;
    Breaks::declareBreakAware();

    if (Breaks::isBreakRequested() &amp;&amp; atSafeState(ctx)) {
        Breaks::signalReady();
        return;
    }

    doFishingWork(ctx);
}
</code></pre> <pre><code>script.onTick(function()
    srs.breaks.declareBreakAware()
    if srs.breaks.isBreakRequested() and atSafeState() then
        srs.breaks.signalReady()
        return
    end
    doFishingWork()
end)

-- Optional: log every phase transition
local handle = srs.breaks.onPhaseChange(function(from, to)
    print("phase " .. from .. " → " .. to)
end)
-- Later: srs.breaks.unsubscribe(handle)
</code></pre>

