C++Lua <pre><code>using namespace srs::api;
// Register once (e.g. in onStart). Runs on the game thread — keep it cheap.
uint64_t token = Chat::onMessage([](const ChatMessageEvent&amp; e) {
    if (e.sender.empty()) {
        // server/system line — minigame + boss status shows up here
        // e.g. if (e.message.find("wave") != std::string::npos) ...
    }
});
// ... later: Chat::offMessage(token);
</code></pre> <pre><code>local myName = srs.player.displayName()

srs.chat.onMessage(function(e)
    -- 1) Minigame / boss status: server messages have an EMPTY sender
    if e.sender == "" then
        if e.message:find("wave") or e.message:find("enrage") then
            log.info("STATUS: " .. e.message)
        end
        return
    end

    -- 2) Someone talking to us by name (public chat has a sender)
    if myName and e.message:lower():find(myName:lower(), 1, true) then
        log.info(e.sender .. " mentioned us: " .. e.message)
    end
end)
</code></pre>

